#include <Python.h>
#include <numpy/arrayobject.h>
#include <stdlib.h>
#include <math.h>

/* LAPACK function signatures */
extern void dgeev_(char *jobvl, char *jobvr, int *n, double *a, int *lda,
                   double *wr, double *wi, double *vl, int *ldvl,
                   double *vr, int *ldvr, double *work, int *lwork,
                   int *info);

static PyObject* py_find_dominant(PyObject* self, PyObject* args) {
    PyObject* py_A;
    if (!PyArg_ParseTuple(args, "O", &py_A)) return NULL;

    PyArrayObject* arr_A = (PyArrayObject*)py_A;
    if (PyArray_NDIM(arr_A) != 2) {
        PyErr_SetString(PyExc_ValueError, "A must be 2D");
        return NULL;
    }

    int n = PyArray_DIM(arr_A, 0);
    if (n != PyArray_DIM(arr_A, 1)) {
        PyErr_SetString(PyExc_ValueError, "A must be square");
        return NULL;
    }

    double* A = (double*)PyArray_DATA(arr_A);

    /* Copy A to a working buffer (dgeev may modify it) */
    double* a_work = (double*)malloc(n * n * sizeof(double));
    memcpy(a_work, A, n * n * sizeof(double));

    /* Allocate workspace */
    int lwork = n * 4;
    double* work = (double*)malloc(lwork * sizeof(double));
    double* wr = (double*)malloc(n * sizeof(double));
    double* wi = (double*)malloc(n * sizeof(double));
    double* vr = (double*)malloc(n * n * sizeof(double));

    char jobvl = 'N';
    char jobvr = 'V';
    int lda = n;
    int ldvl = n;
    int ldvr = n;
    int info = 0;

    dgeev_(&jobvl, &jobvr, &n, a_work, &lda, wr, wi, NULL, &ldvl, vr, &ldvr, work, &lwork, &info);

    /* Find dominant eigenvalue (largest magnitude) */
    int idx = 0;
    double max_mag = 0.0;
    for (int i = 0; i < n; i++) {
        double mag = sqrt(wr[i]*wr[i] + wi[i]*wi[i]);
        if (mag > max_mag) {
            max_mag = mag;
            idx = i;
        }
    }

    /* Build eigenvalue (complex if wi[idx] != 0) */
    double ev_real = wr[idx];
    double ev_imag = wi[idx];

    /* Build eigenvector */
    double* evec = vr + idx * n;

    /* Create numpy arrays for return */
    PyArrayObject* py_evec;
    PyObject* py_eigenval;

    if (ev_imag == 0.0) {
        /* Real eigenvalue */
        py_eigenval = PyFloat_FromDouble(ev_real);
        py_evec = (PyArrayObject*)PyArray_SimpleNewFromData(1, &n, NPY_FLOAT64, evec);
    } else {
        /* Complex eigenvalue - return complex arrays */
        double* evec_complex = (double*)malloc(2 * n * sizeof(double));
        for (int i = 0; i < n; i++) {
            evec_complex[2*i]   = evec[i];
            evec_complex[2*i+1] = 0.0;
        }
        py_eigenval = PyComplex_FromDoubles(ev_real, ev_imag);
        py_evec = (PyArrayObject*)PyArray_SimpleNewFromData(1, &n, NPY_COMPLEX128, evec_complex);
    }

    free(a_work);
    free(work);
    free(wr);
    free(wi);
    free(vr);

    return Py_BuildValue("NO", py_eigenval, py_evec);
}

static PyMethodDef methods[] = {
    {"find_dominant", py_find_dominant, METH_VARARGS, "Find dominant eigenvalue and eigenvector"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "eigen_lapack", NULL, -1, methods
};

PyMODINIT_FUNC PyInit_eigen_lapack(void) {
    import_array();
    return PyModule_Create(&moduledef);
}
EOF

